argv:
$ErrorActionPreference='Stop'
$t=Invoke-RestMethod -UseBasicParsing 'http://127.0.0.1:17410/json/list' -TimeoutSec 3
$target=@($t)|Where-Object { try { ([uri]$_.url).Host -eq 'bugbountyfoto6.files.com' } catch { $false } } | Select-Object -First 1
$ws=[Net.WebSockets.ClientWebSocket]::new();$cts=[Threading.CancellationTokenSource]::new();$cts.CancelAfter(8000)
$ws.ConnectAsync([uri]$target.webSocketDebuggerUrl,$cts.Token).GetAwaiter().GetResult()|Out-Null
$expr=@'
(async()=>{
 const probe=[...document.querySelectorAll('a')].find(e=>(e.textContent||'').trim()==='authz-probe-20260930');
 const row=probe?.closest('tr'); const cb=row?.querySelector('input[type="checkbox"]'); if(cb&&cb.checked){cb.click(); await new Promise(r=>setTimeout(r,250));}
 let b=[...document.querySelectorAll('button')].find(e=>(e.innerText||'').trim()==='New Folder'&&!e.disabled);
 if(!b)return JSON.stringify({error:'New Folder unavailable'});
 b.click(); await new Promise(r=>setTimeout(r,250));
 const d=[...document.querySelectorAll('[role="dialog"]')].find(x=>(x.innerText||'').includes('New folder'));
 if(!d)return JSON.stringify({error:'dialog unavailable'});
 const input=d.querySelector('input[name="name"]'); const create=[...d.querySelectorAll('button')].find(x=>(x.innerText||'').trim()==='Create');
 const setter=Object.getOwnPropertyDescriptor(HTMLInputElement.prototype,'value').set;
 setter.call(input,'move-dest-20260930'); input.dispatchEvent(new Event('input',{bubbles:true})); input.dispatchEvent(new Event('change',{bubbles:true}));
 await new Promise(r=>setTimeout(r,100)); create.click(); await new Promise(r=>setTimeout(r,900));
 return JSON.stringify({exists:[...document.querySelectorAll('a')].some(a=>(a.textContent||'').trim()==='move-dest-20260930')});
})()
'@
$payload=@{id=1;method='Runtime.evaluate';params=@{expression=$expr;returnByValue=$true;awaitPromise=$true}}|ConvertTo-Json -Depth 10 -Compress
$bytes=[Text.Encoding]::UTF8.GetBytes($payload)
$ws.SendAsync([ArraySegment[byte]]::new($bytes),[Net.WebSockets.WebSocketMessageType]::Text,$true,$cts.Token).GetAwaiter().GetResult()|Out-Null
$buf=New-Object byte[] 131072
while($true){$ms=[IO.MemoryStream]::new();do{$r=$ws.ReceiveAsync([ArraySegment[byte]]::new($buf),$cts.Token).GetAwaiter().GetResult();if($r.Count){$ms.Write($buf,0,$r.Count)}}while(-not $r.EndOfMessage);$o=([Text.Encoding]::UTF8.GetString($ms.ToArray())|ConvertFrom-Json);if($o.id -eq 1){Write-Output $o.result.result.value;break}}
$ws.Dispose()
